"use client"

/**
 * Date Picker (Notchset) v1.0.0 · Notchset
 * Docs: https://notchset.dev/components/date-picker
 * MIT licensed: free to use, change and share.
 */

import * as React from "react"
import { Popover } from "radix-ui"

import { cn } from "@/lib/utils"
import { formatDay, useToday, type IsoDay } from "@/lib/notchset/calendar"
import { DatePanel, relative, type QuickPick } from "@/lib/notchset/date-panel"
import { NumberFlow } from "@/lib/notchset/number-flow"
import { useTimeline, usePortal } from "@/lib/notchset/shared"
import { useSound } from "@/lib/notchset/sound"

/*
 * Date Picker (Radix build): a field that opens a calendar with quick picks. Click the month or the
 * year to jump straight there; months slide in from the side you travel to, today has a blue ring, and
 * the field says how far away the date is. Picking pops, fills the day and closes.
 */

interface DatePickerProps extends Omit<React.ComponentPropsWithoutRef<"div">, "defaultValue" | "onChange"> {
  /** The day as "yyyy-mm-dd". */
  value?: IsoDay | null | undefined
  defaultValue?: IsoDay | null | undefined
  onValueChange?: ((value: IsoDay) => void) | undefined
  label?: React.ReactNode | undefined
  /** Under the field; a function gets the chosen day. */
  helper?: React.ReactNode | ((value: IsoDay) => React.ReactNode) | undefined
  placeholder?: string | undefined
  quickPicks?: readonly QuickPick[] | false | undefined
  /** Days that can't be picked. */
  isDisabled?: ((iso: IsoDay) => boolean) | undefined
  sound?: boolean | undefined
}

const DatePicker = React.forwardRef<HTMLDivElement, DatePickerProps>(function DatePicker(
  { value, defaultValue = null, onValueChange, label = "Date", helper, placeholder = "Pick a date", quickPicks, isDisabled, sound = true, className, ...props },
  ref
) {
  const { sfx } = useSound(sound)
  const timeline = useTimeline()
  const container = usePortal()
  const today = useToday()
  const [inner, setInner] = React.useState<IsoDay | null>(defaultValue)
  const day = value === undefined ? inner : value
  const [open, setOpen] = React.useState(false)
  const [opens, setOpens] = React.useState(0)
  const id = React.useId()

  const pick = (iso: IsoDay) => {
    if (value === undefined) setInner(iso)
    onValueChange?.(iso)
    timeline.after(260, () => setOpen(false))
  }

  return (
    <div ref={ref} data-slot="date-picker" data-notchset="" className={cn("flex w-full max-w-[320px] flex-col gap-2", className)} {...props}>
      <span id={`${id}-label`} className="text-[length:var(--ns-type-label)] font-medium text-[var(--foreground)]">
        {label}
      </span>
      <Popover.Root
        open={open}
        onOpenChange={(next) => {
          sfx.tick()
          setOpen(next)
          if (next) setOpens((n) => n + 1)
        }}
      >
        <Popover.Trigger
          aria-labelledby={`${id}-label ${id}-value`}
          className={cn(
            "flex h-11 w-full cursor-pointer items-center gap-2.5 rounded-[var(--radius)] border bg-[var(--background)] px-3.5 text-[length:var(--ns-type-copy)] text-[var(--foreground)] outline-none [transition:border-color_.2s,box-shadow_var(--ns-time-state)] focus-visible:border-[color-mix(in_oklab,var(--foreground)_55%,var(--input))] focus-visible:shadow-[0_0_0_4px_color-mix(in_oklab,var(--foreground)_7%,transparent)]",
            open ? "border-[color-mix(in_oklab,var(--foreground)_55%,var(--input))] shadow-[0_0_0_4px_color-mix(in_oklab,var(--foreground)_7%,transparent)]" : "border-[var(--input)]"
          )}
        >
          <svg viewBox="0 0 24 24" aria-hidden="true" className="size-4 shrink-0 text-[color:var(--ns-ink-support,color-mix(in_oklab,var(--muted-foreground)_85%,var(--foreground)))]" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
            <path d="M8 2v4" />
            <path d="M16 2v4" />
            <rect width="18" height="18" x="3" y="4" rx="2" />
            <path d="M3 10h18" />
          </svg>
          <span id={`${id}-value`} className={cn("font-medium", !day && "font-normal text-[color:var(--ns-ink-support,color-mix(in_oklab,var(--muted-foreground)_85%,var(--foreground)))]")}>
            {day ? <NumberFlow value={formatDay(day, { weekday: "short", month: "short", day: "numeric" })} /> : placeholder}
          </span>
          {day && today && <NumberFlow aria-hidden="true" value={relative(today, day)} className="ms-auto shrink-0 font-mono text-[11px] text-[color-mix(in_oklab,var(--chart-1,var(--foreground))_80%,var(--foreground))]" />}
        </Popover.Trigger>
        <Popover.Portal container={container}>
          <Popover.Content
            data-slot="date-picker-popup"
            aria-label="Choose a date"
            side="bottom"
            align="start"
            sideOffset={8}
            className="z-50 w-[300px] origin-top-left animate-[ns-menu-fade_.16s,ns-menu-pop_.34s_var(--ns-ease-reshape)] rounded-[calc(min(var(--radius),16px)+4px)] border border-[var(--border)] bg-[var(--background)] p-3 text-[var(--foreground)] shadow-[0_20px_44px_-18px_rgba(0,0,0,.28)] outline-none rtl:origin-top-right"
          >
            <DatePanel key={opens} value={day} onPick={pick} quickPicks={quickPicks} isDisabled={isDisabled} sound={sound} />
          </Popover.Content>
        </Popover.Portal>
      </Popover.Root>
      {helper && day && <span className="text-[length:var(--ns-type-note)] text-[color:var(--ns-ink-support,color-mix(in_oklab,var(--muted-foreground)_85%,var(--foreground)))]">{typeof helper === "function" ? helper(day) : helper}</span>}
    </div>
  )
})

export { DatePicker, type DatePickerProps }

"use client"

import * as React from "react"

import { cn } from "@/lib/utils"
import { addDays, CalendarGrid, diffDays, formatDay, fromIso, MONTHS, shiftView, todayIso, useToday, type DayInfo, type IsoDay } from "@/lib/notchset/calendar"
import { useSound } from "@/lib/notchset/sound"

/*
 * Date Picker's shared parts (both builds wrap them in their own popover): the calendar panel with its
 * Month and Year jumps, quick picks on one line, and three views in one box (days, months, years); the
 * day cell; and the trigger's relative hint ("in 7 days", "tomorrow", "3 days ago").
 */

interface QuickPick {
  label: string
  /** Days from today. */
  days: number
}

const QUICK: readonly QuickPick[] = [
  { label: "Today", days: 0 },
  { label: "Tomorrow", days: 1 },
  { label: "Next Mon", days: -1 },
  { label: "+2 weeks", days: 14 },
]

/** "Next Mon" is the coming Monday; every other pick is a day offset. */
function quickDay(today: IsoDay, pick: QuickPick) {
  if (pick.days >= 0) return addDays(today, pick.days)
  const dow = fromIso(today).getDay()
  return addDays(today, ((8 - dow) % 7) || 7)
}

function relative(today: IsoDay | null, iso: IsoDay) {
  if (!today) return ""
  const d = diffDays(today, iso)
  return d === 0 ? "today" : d === 1 ? "tomorrow" : d === -1 ? "yesterday" : d > 0 ? `in ${d} days` : `${-d} days ago`
}

/** The day as Date Picker draws it: a filled pick, a blue ring and dot for today, muted weekends. */
function DateCell({ info }: { info: DayInfo }) {
  return (
    <>
      <span
        aria-hidden="true"
        className={cn(
          "absolute inset-x-[3px] inset-y-0.5 rounded-[min(var(--radius),12px)] [transition:background-color_.2s,transform_.35s_var(--ns-ease-rebound),scale_.35s_var(--ns-ease-rebound),translate_.35s_var(--ns-ease-rebound),rotate_.35s_var(--ns-ease-rebound)]",
          info.selected ? "scale-100 bg-[var(--foreground)]" : "scale-90 group-hover/day:bg-[var(--accent)] group-focus-visible/day:bg-[var(--accent)]",
          info.today && !info.selected && "shadow-[inset_0_0_0_1.5px_var(--chart-1,var(--ring))]",
          !info.inMonth && "group-hover/day:bg-transparent"
        )}
      />
      <span
        className={cn(
          "relative text-[length:var(--ns-type-label)] tabular-nums",
          info.selected || info.today ? "font-semibold" : "font-normal",
          info.selected && "text-[var(--background)]",
          !info.selected && !info.inMonth && "text-[color-mix(in_oklab,var(--muted-foreground)_45%,transparent)]",
          !info.selected && info.inMonth && info.weekend && "text-[color:var(--ns-ink-support,color-mix(in_oklab,var(--muted-foreground)_85%,var(--foreground)))]",
          !info.selected && info.inMonth && !info.weekend && "text-[var(--foreground)]"
        )}
      >
        {info.day}
      </span>
      {info.today && <span aria-hidden="true" className={cn("absolute bottom-[5px] left-1/2 size-1 -translate-x-1/2 rounded-full", info.selected ? "bg-[var(--background)]" : "bg-[var(--chart-1,var(--ring))]")} />}
    </>
  )
}

interface DatePanelProps {
  value: IsoDay | null
  onPick: (iso: IsoDay) => void
  quickPicks?: readonly QuickPick[] | false | undefined
  isDisabled?: ((iso: IsoDay) => boolean) | undefined
  sound?: boolean | undefined
}

/** The popover's contents. Mount it fresh on every open (a key), so it opens on the chosen month. */
function DatePanel({ value, onPick, quickPicks = QUICK, isDisabled, sound = true }: DatePanelProps) {
  const { sfx } = useSound(sound)
  const today = useToday()
  const start = value ?? today ?? todayIso()
  const [view, setView] = React.useState<[number, number]>(() => [fromIso(start).getFullYear(), fromIso(start).getMonth()])
  const [mode, setMode] = React.useState<"days" | "months" | "years">("days")
  const [slide, setSlide] = React.useState({ key: 0, dir: 1 as 1 | -1 })
  const [focusIso, setFocusIso] = React.useState(start)

  const go = (dir: 1 | -1) => {
    sfx.turn(dir)
    setView((v) => shiftView(v, dir))
    setSlide((s) => ({ key: s.key + 1, dir }))
  }
  const toView = (iso: IsoDay) => {
    const d = fromIso(iso)
    const next: [number, number] = [d.getFullYear(), d.getMonth()]
    if (next[0] !== view[0] || next[1] !== view[1]) {
      const dir = next[0] * 12 + next[1] > view[0] * 12 + view[1] ? 1 : -1
      setView(next)
      setSlide((s) => ({ key: s.key + 1, dir }))
    }
  }
  const pick = (iso: IsoDay) => {
    sfx.pop()
    toView(iso)
    onPick(iso)
  }
  const yearsFrom = view[0] - 5

  return (
    <div data-slot="date-panel" className="flex flex-col">
      <div className="flex items-center justify-between px-0.5 pt-0.5 pb-2">
        <span className="flex items-center gap-0.5">
          <button
            type="button"
            aria-expanded={mode === "months"}
            onClick={() => {
              sfx.tick()
              setMode((m) => (m === "months" ? "days" : "months"))
            }}
            className={cn("flex h-[30px] cursor-pointer items-center gap-1 rounded-[8px] px-2 text-[15px] font-semibold tracking-[var(--ns-tracking-control)] text-[var(--foreground)] outline-none hover:bg-[var(--accent)] focus-visible:ring-[length:var(--ns-focus-width,2px)] focus-visible:ring-[color:var(--ns-focus-color,var(--ring))]", mode === "months" && "bg-[var(--accent)]")}
          >
            {MONTHS[view[1]]}
            <svg viewBox="0 0 24 24" aria-hidden="true" className={cn("size-3.5 [transition:transform_.3s_var(--ns-ease-pop),scale_.3s_var(--ns-ease-pop),translate_.3s_var(--ns-ease-pop),rotate_.3s_var(--ns-ease-pop)]", mode === "months" && "rotate-180")} fill="none" stroke="currentColor" strokeWidth="2.2" strokeLinecap="round" strokeLinejoin="round">
              <path d="m6 9 6 6 6-6" />
            </svg>
          </button>
          <button
            type="button"
            aria-expanded={mode === "years"}
            onClick={() => {
              sfx.tick()
              setMode((m) => (m === "years" ? "days" : "years"))
            }}
            className={cn(
              "flex h-[30px] cursor-pointer items-center gap-1 rounded-[8px] px-2 font-mono text-[length:var(--ns-type-label)] outline-none hover:bg-[var(--accent)] hover:text-[var(--foreground)] focus-visible:ring-[length:var(--ns-focus-width,2px)] focus-visible:ring-[color:var(--ns-focus-color,var(--ring))]",
              mode === "years" ? "bg-[var(--accent)] text-[var(--foreground)]" : "text-[color:var(--ns-ink-support,color-mix(in_oklab,var(--muted-foreground)_85%,var(--foreground)))]"
            )}
          >
            {view[0]}
            <svg viewBox="0 0 24 24" aria-hidden="true" className={cn("size-3 [transition:transform_.3s_var(--ns-ease-pop),scale_.3s_var(--ns-ease-pop),translate_.3s_var(--ns-ease-pop),rotate_.3s_var(--ns-ease-pop)]", mode === "years" && "rotate-180")} fill="none" stroke="currentColor" strokeWidth="2.2" strokeLinecap="round" strokeLinejoin="round">
              <path d="m6 9 6 6 6-6" />
            </svg>
          </button>
        </span>
        {mode === "days" && (
          <span className="flex items-center">
            {([-1, 1] as const).map((dir) => (
              <button
                key={dir}
                type="button"
                aria-label={dir < 0 ? "Previous month" : "Next month"}
                onClick={() => go(dir)}
                className="grid size-7 cursor-pointer place-items-center rounded-[8px] text-[var(--foreground)] outline-none hover:bg-[var(--accent)] focus-visible:ring-[length:var(--ns-focus-width,2px)] focus-visible:ring-[color:var(--ns-focus-color,var(--ring))] active:scale-[.9]"
              >
                <svg viewBox="0 0 24 24" aria-hidden="true" className="size-4 rtl:-scale-x-100" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
                  <path d={dir < 0 ? "m15 18-6-6 6-6" : "m9 18 6-6-6-6"} />
                </svg>
              </button>
            ))}
          </span>
        )}
      </div>
      {quickPicks && today && (
        <div className="mb-1.5 flex gap-1 border-b border-[var(--border)] pb-2.5">
          {quickPicks.map((q) => {
            const iso = quickDay(today, q)
            const on = iso === value
            return (
              <button
                key={q.label}
                type="button"
                aria-pressed={on}
                onClick={() => {
                  setFocusIso(iso)
                  setMode("days")
                  pick(iso)
                }}
                className={cn(
                  "inline-flex h-[26px] min-w-0 flex-[1_1_auto] cursor-pointer items-center justify-center truncate rounded-[var(--radius)] border border-[var(--border)] px-2 text-[11px] font-medium outline-none [transition:transform_var(--ns-time-press)_var(--ns-ease-press),scale_var(--ns-time-press)_var(--ns-ease-press),translate_var(--ns-time-press)_var(--ns-ease-press),rotate_var(--ns-time-press)_var(--ns-ease-press),background-color_.2s,color_.2s] focus-visible:ring-[length:var(--ns-focus-width,2px)] focus-visible:ring-[color:var(--ns-focus-color,var(--ring))] active:scale-[.95]",
                  on ? "bg-[var(--foreground)] text-[var(--background)]" : "bg-[var(--background)] text-[var(--foreground)] hover:bg-[var(--accent)]"
                )}
              >
                {q.label}
              </button>
            )
          })}
        </div>
      )}
      {mode === "days" && (
        <CalendarGrid
          year={view[0]}
          month={view[1]}
          slideKey={slide.key}
          dir={slide.dir}
          focusIso={focusIso}
          onFocusIso={(iso) => {
            setFocusIso(iso)
            toView(iso)
          }}
          onPick={pick}
          isSelected={(iso) => iso === value}
          isDisabled={isDisabled}
          renderDay={(info) => <DateCell info={info} />}
          label={`${MONTHS[view[1]]} ${view[0]}`}
        />
      )}
      {mode !== "days" && (
        <div key={mode} className="grid animate-[ns-reveal_.3s_cubic-bezier(.2,.8,.2,1)_both] grid-cols-3 gap-1.5 pt-1.5 pb-0.5">
          {Array.from({ length: 12 }, (_, i) => {
            const isMonths = mode === "months"
            const on = isMonths ? i === view[1] : yearsFrom + i === view[0]
            const now = today ? (isMonths ? view[0] === fromIso(today).getFullYear() && i === fromIso(today).getMonth() : yearsFrom + i === fromIso(today).getFullYear()) : false
            return (
              <button
                key={i}
                type="button"
                aria-pressed={on}
                onClick={() => {
                  sfx.tone(800 + i * 40, 0.03, "triangle", 0.035)
                  if (isMonths) {
                    const dir = i >= view[1] ? 1 : -1
                    setView([view[0], i])
                    setSlide((s) => ({ key: s.key + 1, dir }))
                    setMode("days")
                  } else {
                    setView([yearsFrom + i, view[1]])
                    setMode("months")
                  }
                }}
                className={cn(
                  "h-[42px] cursor-pointer rounded-[min(var(--radius),12px)] text-[length:var(--ns-type-label)] outline-none [transition:background-color_.2s,transform_.15s,scale_.15s,translate_.15s,rotate_.15s] focus-visible:ring-[length:var(--ns-focus-width,2px)] focus-visible:ring-[color:var(--ns-focus-color,var(--ring))] active:scale-[.95]",
                  on ? "bg-[var(--foreground)] font-semibold text-[var(--background)]" : "font-normal text-[var(--foreground)] hover:bg-[var(--accent)]",
                  now && !on && "shadow-[inset_0_0_0_1.5px_var(--chart-1,var(--ring))]",
                  !isMonths && "font-mono"
                )}
              >
                {isMonths ? MONTHS[i]!.slice(0, 3) : yearsFrom + i}
              </button>
            )
          })}
        </div>
      )}
    </div>
  )
}

export { DateCell, DatePanel, formatDay, relative, type DatePanelProps, type QuickPick }

"use client"

import * as React from "react"

import { cn } from "@/lib/utils"

/*
 * Calendar parts shared by Date Picker, Range Picker and Agenda Calendar: ISO day helpers (yyyy-mm-dd,
 * local time) and a month grid. The grid starts weeks on Monday, rings today in --chart-1, slides in
 * from the direction you travel, and follows the grid keyboard pattern: arrows move a day, PageUp and
 * PageDown a month, Home and End to the ends of the week. Days outside the month are shown but inactive
 * (moving onto one by keyboard turns the month). Each picker draws its own day (renderDay).
 */

/** A day as "yyyy-mm-dd". */
type IsoDay = string

const two = (n: number) => String(n).padStart(2, "0")
const toIso = (d: Date): IsoDay => `${d.getFullYear()}-${two(d.getMonth() + 1)}-${two(d.getDate())}`
/** Noon, so daylight-saving shifts never move the day. */
const fromIso = (iso: IsoDay) => {
  const [y, m, d] = iso.split("-").map(Number)
  return new Date(y!, m! - 1, d!, 12)
}
const todayIso = () => toIso(new Date())
const noSubscribe = () => () => {}
/** Today in the visitor's own time zone; null while server rendering, so the server never guesses it. */
function useToday(): IsoDay | null {
  return React.useSyncExternalStore(noSubscribe, todayIso, () => null)
}
const addDays = (iso: IsoDay, n: number) => {
  const d = fromIso(iso)
  d.setDate(d.getDate() + n)
  return toIso(d)
}
const addMonths = (iso: IsoDay, n: number) => {
  const d = fromIso(iso)
  const day = d.getDate()
  d.setDate(1)
  d.setMonth(d.getMonth() + n)
  d.setDate(Math.min(day, new Date(d.getFullYear(), d.getMonth() + 1, 0).getDate()))
  return toIso(d)
}
const diffDays = (a: IsoDay, b: IsoDay) => Math.round((fromIso(b).getTime() - fromIso(a).getTime()) / 86400000)
/** The month after (n = 1) or before (n = -1) a [year, month] view. */
const shiftView = ([y, m]: readonly [number, number], n: number): [number, number] => {
  const d = new Date(y, m + n, 1)
  return [d.getFullYear(), d.getMonth()]
}
/** `count` days from the Monday on or before the 1st. */
function monthDays(year: number, month: number, count = 42): IsoDay[] {
  const first = new Date(year, month, 1, 12)
  const start = new Date(first)
  start.setDate(1 - ((first.getDay() + 6) % 7))
  return Array.from({ length: count }, (_, i) => {
    const d = new Date(start)
    d.setDate(start.getDate() + i)
    return toIso(d)
  })
}
const formatDay = (iso: IsoDay, options: Intl.DateTimeFormatOptions, locale = "en-US") => fromIso(iso).toLocaleDateString(locale, options)
const MONTHS = Array.from({ length: 12 }, (_, i) => new Date(2026, i, 1).toLocaleDateString("en-US", { month: "long" }))
const WEEKDAYS = ["Mo", "Tu", "We", "Th", "Fr", "Sa", "Su"]

interface DayInfo {
  iso: IsoDay
  day: number
  inMonth: boolean
  today: boolean
  weekend: boolean
  selected: boolean
  disabled: boolean
}

interface CalendarGridProps {
  year: number
  /** 0–11. */
  month: number
  /** Cells shown: 42 (six weeks) or 35. */
  count?: number | undefined
  /** Changes on every month change, so the grid slides in; `dir` is the direction of travel. */
  slideKey?: number | string | undefined
  dir?: 1 | -1 | undefined
  /** The day that holds keyboard focus (roving tabindex). */
  focusIso: IsoDay
  onFocusIso: (iso: IsoDay) => void
  onPick: (iso: IsoDay) => void
  onHoverIso?: ((iso: IsoDay | null) => void) | undefined
  isSelected?: ((iso: IsoDay) => boolean) | undefined
  isDisabled?: ((iso: IsoDay) => boolean) | undefined
  renderDay: (info: DayInfo) => React.ReactNode
  /** Cell height in px. Default 36. */
  cellHeight?: number | undefined
  label: string
  className?: string | undefined
}

function CalendarGrid({ year, month, count = 42, slideKey, dir = 1, focusIso, onFocusIso, onPick, onHoverIso, isSelected, isDisabled, renderDay, cellHeight = 36, label, className }: CalendarGridProps) {
  const days = monthDays(year, month, count)
  const today = useToday()
  const bodyRef = React.useRef<HTMLDivElement>(null)
  const moved = React.useRef(false)
  const tabIso = days.includes(focusIso) ? focusIso : (days.find((d) => isSelected?.(d)) ?? days.find((d) => fromIso(d).getMonth() === month)!)

  // After a keyboard move, the day that took focus gets it (also after the month slides).
  React.useEffect(() => {
    if (!moved.current) return
    moved.current = false
    bodyRef.current?.querySelector<HTMLElement>(`[data-iso="${focusIso}"]`)?.focus()
  }, [focusIso, slideKey])

  const onKey = (event: React.KeyboardEvent, iso: IsoDay) => {
    const rtl = (event.currentTarget as HTMLElement).closest("[dir=rtl]") != null
    const dow = (fromIso(iso).getDay() + 6) % 7
    let next: IsoDay | null = null
    if (event.key === "ArrowRight") next = addDays(iso, rtl ? -1 : 1)
    else if (event.key === "ArrowLeft") next = addDays(iso, rtl ? 1 : -1)
    else if (event.key === "ArrowDown") next = addDays(iso, 7)
    else if (event.key === "ArrowUp") next = addDays(iso, -7)
    else if (event.key === "PageDown") next = addMonths(iso, event.shiftKey ? 12 : 1)
    else if (event.key === "PageUp") next = addMonths(iso, event.shiftKey ? -12 : -1)
    else if (event.key === "Home") next = addDays(iso, -dow)
    else if (event.key === "End") next = addDays(iso, 6 - dow)
    if (!next) return
    event.preventDefault()
    moved.current = true
    onFocusIso(next)
  }

